"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";
import { Switch } from "@/components/motion/switch";
import { cn } from "@/lib/utils";

import { formatDay, sampleDate } from "../lib/format";
import { BlockFrame } from "../parts/block-frame";
import { KPI_RANGES, type KpiId, type KpiRange, KPIS, readKpi } from "./kpi-drilldown/data";
import { KpiCard } from "./kpi-drilldown/kpi-card";
import { KpiDetail } from "./kpi-drilldown/kpi-detail";

// Critically damped (damping is 2 * sqrt(stiffness)): the view grows out of its card and settles with no wobble.
const GROW: Transition = { type: "spring", stiffness: 380, damping: 39, mass: 1 };
const INSTANT: Transition = { duration: 0 };

const noop = () => {};

const STEP = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 } as const;

const isStepKey = (key: string): key is keyof typeof STEP => key in STEP;

/**
 * Four figures in a grid. A card grows in place into its daily chart and the
 * clinics behind it, then shrinks back to the same card. In a wide frame the
 * grid already holds the height of that view, so opening a card moves nothing
 * below it. In a narrow frame the cards keep their own height and the view
 * takes their place.
 * Focus follows: to Close on the way in, back to the card on the way out.
 */
export function KpiDrilldown({ className }: { className?: string }) {
  const [range, setRange] = useState<KpiRange>("30");
  const [compare, setCompare] = useState(true);
  const [openId, setOpenId] = useState<KpiId | null>(null);
  // The card that holds the grid's one tab stop.
  const [activeId, setActiveId] = useState<KpiId>("bookings");
  const reduceMotion = useReducedMotion();
  const titleId = useId();
  const compareId = useId();
  const closeRef = useRef<HTMLButtonElement | null>(null);
  const cards = useRef(new Map<KpiId, HTMLButtonElement>());
  const returnTo = useRef<KpiId | null>(null);
  const detailRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (openId) {
      closeRef.current?.focus({ preventScroll: true });
      // On a phone the card can sit far below the top of the view it opens. Bring the view's top into sight.
      detailRef.current?.scrollIntoView({ block: "nearest" });
    } else if (returnTo.current) {
      cards.current.get(returnTo.current)?.focus();
      returnTo.current = null;
    }
  }, [openId]);

  const open = (id: KpiId) => {
    setActiveId(id);
    setOpenId(id);
  };

  const close = () => {
    returnTo.current = openId;
    setOpenId(null);
  };

  const handleGridKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const current = KPIS.findIndex((kpi) => kpi.id === activeId);
    let index: number;
    if (event.key === "Home") index = 0;
    else if (event.key === "End") index = KPIS.length - 1;
    else if (!isStepKey(event.key)) return;
    else index = Math.min(KPIS.length - 1, Math.max(0, current + STEP[event.key]));
    event.preventDefault();
    const next = KPIS[index];
    if (!next) return;
    setActiveId(next.id);
    cards.current.get(next.id)?.focus();
  };

  const length = Number(range);
  const openKpi = KPIS.find((kpi) => kpi.id === openId) ?? null;
  const sizerKpi = openKpi ?? KPIS.find((kpi) => kpi.id === activeId) ?? KPIS[0]!;
  // With reduced motion the card and the view share no surface, so the view appears at once.
  const surfaceId = (id: KpiId) => (reduceMotion ? undefined : `${titleId}-${id}`);
  const grow = reduceMotion ? INSTANT : GROW;

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Clinic activity
          </h2>
          <p className="truncate text-sm text-muted-foreground">
            {formatDay(sampleDate(length - 1))} to {formatDay(sampleDate(0))}, five clinics
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
          <label htmlFor={compareId} className="flex min-h-11 cursor-pointer items-center gap-2 text-sm whitespace-nowrap text-muted-foreground sm:min-h-9">
            Show period before
            <Switch id={compareId} checked={compare} onCheckedChange={setCompare} />
          </label>
          <SegmentedControl aria-label="Date range" options={KPI_RANGES} value={range} onValueChange={setRange} />
        </div>
      </header>

      <div className="relative grid">
        {/* An unseen copy of the detail view sets the height, so the grid and the view are the same size. */}
        <div aria-hidden="true" inert className="invisible col-start-1 row-start-1 hidden min-w-0 @md:block">
          <KpiDetail kpi={sizerKpi} range={range} compare={compare} onClose={noop} />
        </div>

        <div
          role="group"
          aria-label="Figures. Use the arrow keys to move between cards, then Enter to open one."
          inert={openKpi !== null}
          onKeyDown={handleGridKeyDown}
          className={cn(
            "col-start-1 row-start-1 min-w-0 grid-cols-2 gap-px bg-border @md:grid @md:auto-rows-fr",
            // In a narrow frame the open view takes the grid's place, so the cards leave the flow.
            openKpi ? "hidden" : "grid",
          )}
        >
          {KPIS.map((kpi) => {
            const figures = readKpi(kpi, range);
            return (
              <KpiCard
                key={kpi.id}
                kpi={kpi}
                total={figures.now}
                change={compare ? figures.change : null}
                values={figures.current}
                tabStop={kpi.id === activeId}
                layoutId={surfaceId(kpi.id)}
                layoutDependency={openId}
                transition={grow}
                onOpen={() => open(kpi.id)}
                onFocus={() => setActiveId(kpi.id)}
                buttonRef={(node) => {
                  if (node) cards.current.set(kpi.id, node);
                  else cards.current.delete(kpi.id);
                }}
              />
            );
          })}
        </div>

        <AnimatePresence initial={false}>
          {openKpi ? (
            // The surface shares its id with the card, so it grows from the card's own place and size.
            <motion.div
              key="surface"
              aria-hidden="true"
              layoutId={surfaceId(openKpi.id)}
              layoutDependency={openId}
              transition={grow}
              className="absolute inset-0 bg-card"
            />
          ) : null}
          {openKpi ? (
            <motion.div
              key="detail"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1, transition: reduceMotion ? INSTANT : { duration: 0.2, delay: 0.08 } }}
              exit={{ opacity: 0, transition: reduceMotion ? INSTANT : { duration: 0.1 } }}
              ref={detailRef}
              className="relative col-start-1 row-start-1 min-w-0 @md:absolute @md:inset-0"
            >
              <KpiDetail kpi={openKpi} range={range} compare={compare} onClose={close} closeRef={closeRef} />
            </motion.div>
          ) : null}
        </AnimatePresence>
      </div>
    </BlockFrame>
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

import { makeSeries, percentChange, sum } from "../../lib/plot";

/** How many days the block shows. */
export type KpiRange = "7" | "30" | "90";

/** The four figures the block tracks. */
export type KpiId = "bookings" | "patients" | "cancellations" | "noShows";

/** One figure: its daily counts and how its total splits across the clinics. */
export interface Kpi {
  id: KpiId;
  label: string;
  /** The noun used in a sentence, such as "bookings". */
  noun: string;
  /** Whole daily counts for 180 days: the newest 90 are the period, the 90 before are the comparison. */
  days: number[];
  lowerIsBetter: boolean;
  /** Each clinic's share of the total, in clinic order, for the period and for the period before. */
  shares: { now: number[]; before: number[] };
}

/** One clinic's row in the breakdown table. */
export interface ClinicRow {
  clinic: string;
  now: number;
  before: number;
  /** Percent change from the period before. */
  change: number;
  /** This clinic's percent of the period total. */
  share: number;
}

/** The range choices, in the order the control shows them. */
export const KPI_RANGES: { value: KpiRange; label: string }[] = [
  { value: "7", label: "7 days" },
  { value: "30", label: "30 days" },
  { value: "90", label: "90 days" },
];

/** The clinics, in the order every share list uses. */
export const CLINICS = ["Harbour Street", "Mill Lane", "Northgate", "Orchard Road", "The Quay"];

const wholeDays = (seed: number, start: number, end: number, noise: number) =>
  makeSeries(seed, 180, start, end, noise).map(Math.round);

/** The four figures with their sample data. */
export const KPIS: Kpi[] = [
  {
    id: "bookings",
    label: "Bookings",
    noun: "bookings",
    days: wholeDays(211, 124, 188, 30),
    lowerIsBetter: false,
    shares: { now: [0.31, 0.24, 0.2, 0.15, 0.1], before: [0.29, 0.26, 0.2, 0.14, 0.11] },
  },
  {
    id: "patients",
    label: "New patients",
    noun: "new patients",
    days: wholeDays(223, 19, 34, 8),
    lowerIsBetter: false,
    shares: { now: [0.27, 0.22, 0.24, 0.17, 0.1], before: [0.3, 0.23, 0.2, 0.16, 0.11] },
  },
  {
    id: "cancellations",
    label: "Cancellations",
    noun: "cancellations",
    days: wholeDays(239, 17, 21, 6),
    lowerIsBetter: true,
    shares: { now: [0.26, 0.3, 0.18, 0.16, 0.1], before: [0.28, 0.25, 0.2, 0.16, 0.11] },
  },
  {
    id: "noShows",
    label: "No-shows",
    noun: "no-shows",
    days: wholeDays(251, 15, 9, 5),
    lowerIsBetter: true,
    shares: { now: [0.24, 0.21, 0.19, 0.22, 0.14], before: [0.27, 0.24, 0.2, 0.17, 0.12] },
  },
];

/** The figures of one metric over one range: the period, the period before it, both totals and the change. */
export function readKpi(kpi: Kpi, range: KpiRange) {
  const length = Number(range);
  const current = kpi.days.slice(-length);
  const previous = kpi.days.slice(-length * 2, -length);
  const now = sum(current);
  const before = sum(previous);
  return { current, previous, now, before, change: percentChange(before, now) };
}

/** Splits a whole total by shares into whole parts that add up to it. The first part takes the rounding remainder. */
export function splitByShares(total: number, shares: number[]): number[] {
  const parts = shares.map((share) => Math.round(total * share));
  parts[0] = (parts[0] ?? 0) + total - sum(parts);
  return parts;
}

/** The breakdown of one figure by clinic. The rows add up to the period total and to the total before. */
export function clinicRows(kpi: Kpi, range: KpiRange): ClinicRow[] {
  const { now, before } = readKpi(kpi, range);
  const nowParts = splitByShares(now, kpi.shares.now);
  const beforeParts = splitByShares(before, kpi.shares.before);
  return CLINICS.map((clinic, index) => {
    const value = nowParts[index] ?? 0;
    const earlier = beforeParts[index] ?? 0;
    return {
      clinic,
      now: value,
      before: earlier,
      change: percentChange(earlier, value),
      share: now === 0 ? 0 : (value / now) * 100,
    };
  });
}

/**
 * Plot maths shared by the blocks. Every path is drawn in a 0 to 100 box, and
 * the SVG stretches it with `preserveAspectRatio="none"`, so a chart needs no
 * resize observer. Strokes keep their width through `vector-effect`.
 */

/** A repeatable random source, so sample data is the same on the server and in the browser. */
export function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

// Monday to Sunday: a working week that tails off, then a quiet weekend.
const WEEKDAY_LIFT = [0.35, 0.5, 0.2, 0.1, -0.05, -0.75, -1];

/** Sample data that moves from `start` to `end` with a working-week rhythm and some noise. */
export function makeSeries(seed: number, length: number, start: number, end: number, noise: number): number[] {
  const random = seededRandom(seed);
  return Array.from({ length }, (_, index) => {
    const progress = length === 1 ? 1 : index / (length - 1);
    const trend = start + (end - start) * progress;
    const week = (WEEKDAY_LIFT[index % 7] ?? 0) * noise * 0.6;
    return Math.max(0, trend + week + (random() - 0.5) * noise * 0.7);
  });
}

/** The lowest and highest value across several series, padded so a line never touches the frame. */
export function paddedExtent(series: number[][], padding = 0.12): [number, number] {
  const values = series.flat();
  const low = Math.min(...values);
  const high = Math.max(...values);
  const span = high - low || 1;
  return [Math.max(0, low - span * padding), high + span * padding];
}

/** Where a value sits in the box, from 0 at the top to 100 at the bottom. */
export function toY(value: number, [low, high]: [number, number]): number {
  return 100 - ((value - low) / (high - low || 1)) * 100;
}

/** Where a point sits across the box, from 0 to 100. */
export function toX(index: number, length: number): number {
  return length <= 1 ? 50 : (index / (length - 1)) * 100;
}

/** The value at a fractional position along a series, read off the straight line between its neighbours. */
function valueAt(values: number[], position: number): number {
  const left = Math.floor(position);
  const right = Math.min(values.length - 1, left + 1);
  const from = values[left] ?? 0;
  const to = values[right] ?? from;
  return from + (to - from) * (position - left);
}

/**
 * A line through `values` with a fixed number of segments. Two paths with the
 * same segment count can morph into each other, whatever their point counts.
 */
export function linePath(values: number[], extent: [number, number], samples = 60): string {
  if (values.length === 0) return "";
  const parts: string[] = [];
  for (let step = 0; step <= samples; step += 1) {
    const position = (step / samples) * (values.length - 1);
    const x = (step / samples) * 100;
    const y = toY(valueAt(values, position), extent);
    parts.push(`${step === 0 ? "M" : "L"}${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return parts.join(" ");
}

/** The same line, closed down to the bottom edge, for a filled area. */
export function areaPath(values: number[], extent: [number, number], samples = 60): string {
  const line = linePath(values, extent, samples);
  return line ? `${line} L100 100 L0 100 Z` : "";
}

/** Round axis values between the low and high of the plot. */
export function axisTicks([low, high]: [number, number], count = 4): number[] {
  return Array.from({ length: count }, (_, index) => low + ((high - low) * index) / (count - 1));
}

/** The percent change from `before` to `after`, or 0 when there is nothing to compare against. */
export function percentChange(before: number, after: number): number {
  return before === 0 ? 0 : ((after - before) / before) * 100;
}

/** The sum of a series. */
export function sum(values: number[]): number {
  return values.reduce((total, value) => total + value, 0);
}

/** The mean of a series. */
export function mean(values: number[]): number {
  return values.length === 0 ? 0 : sum(values) / values.length;
}

"use client";

import { motion, type Transition } from "motion/react";

import { MaximizeIcon } from "@/components/blocks/parts/icons";
import { NumberTicker } from "@/components/motion/number-ticker";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { ROLL_WHOLE } from "../../lib/roll-formats";
import { Delta } from "../../parts/delta";
import { Sparkline } from "../../parts/sparkline";
import type { Kpi } from "./data";

/** Props for one figure card. */
export interface KpiCardProps {
  kpi: Kpi;
  /** The period total. */
  total: number;
  /** The percent change on the period before, or null when the comparison is off. */
  change: number | null;
  /** The daily values of the period, for the sparkline. */
  values: number[];
  /** True for the one card in the grid that Tab reaches. */
  tabStop: boolean;
  /** Shared with the detail surface, so the detail grows out of this card. Leave it out for no motion. */
  layoutId?: string;
  /** Changes when a card opens or closes, the only time the surface is measured again. */
  layoutDependency: string | null;
  /** The spring the surface uses on the way back to the card. */
  transition: Transition;
  onOpen: () => void;
  onFocus: () => void;
  /** Hands the button to the grid, so it can move focus with the arrow keys. */
  buttonRef: (node: HTMLButtonElement | null) => void;
}

/**
 * One figure with its trend. The whole card is a button that opens the detail
 * view, so the target is as large as the card. Its surface is the shape the
 * detail view grows from.
 */
export function KpiCard({ kpi, total, change, values, tabStop, layoutId, layoutDependency, transition, onOpen, onFocus, buttonRef }: KpiCardProps) {
  return (
    <Button
      ref={buttonRef}
      variant="ghost"
      size="sm"
      tabIndex={tabStop ? 0 : -1}
      onClick={onOpen}
      onFocus={onFocus}
      className="group relative min-h-11 items-stretch text-left focus-visible:z-10 active:scale-100"
    >
      <motion.span
        aria-hidden="true"
        layoutId={layoutId}
        layoutDependency={layoutDependency}
        transition={transition}
        className="absolute inset-0 bg-card"
      />
      <span aria-hidden="true" className="absolute inset-0 group-hover:bg-muted/40" />
      <span className="relative flex flex-1 flex-col gap-3 p-5">
      <span className="relative flex items-start justify-between gap-3">
        <span className="truncate text-sm font-normal text-muted-foreground">{kpi.label}</span>
        <MaximizeIcon
          aria-hidden="true"
          className="size-4 shrink-0 text-muted-foreground group-hover:text-foreground group-focus-visible:text-foreground"
        />
      </span>
      <span className="relative flex flex-col gap-1">
        <NumberTicker value={Math.round(total)} format={ROLL_WHOLE} className="text-3xl font-semibold tracking-tight" />
        {/* The line keeps its height when the comparison is off, so the card never changes size. */}
        <span className={cn("flex h-4 items-center gap-1.5 text-xs font-normal whitespace-nowrap text-muted-foreground", change === null ? "invisible" : undefined)}>
          <Delta value={change ?? 0} lowerIsBetter={kpi.lowerIsBetter} />
          vs before
        </span>
      </span>
      {/* The box sizes the line: a Button gives any svg without a size class the icon size. */}
      <span className="relative h-10 w-full">
        <Sparkline values={values} className="size-full group-hover:text-chart-1 group-focus-visible:text-chart-1" />
      </span>
      <span className="sr-only">Open the detail view</span>
      </span>
    </Button>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

/** A warning triangle, from the chosen icon pack. */
export const AlertTriangleIcon = packIcon("alert-triangle");
/** An arrow that points down, from the chosen icon pack. */
export const ArrowDownIcon = packIcon("arrow-up", "rotate-180");
/** An arrow that points left, from the chosen icon pack. */
export const ArrowLeftIcon = packIcon("arrow-up", "-rotate-90");
/** An arrow that points up, from the chosen icon pack. */
export const ArrowUpIcon = packIcon("arrow-up");
/** A bell, from the chosen icon pack. */
export const BellIcon = packIcon("bell");
/** A calendar, from the chosen icon pack. */
export const CalendarIcon = packIcon("calendar");
/** A check mark, from the chosen icon pack. */
export const CheckIcon = packIcon("check");
/** A chevron that points down, from the chosen icon pack. */
export const ChevronDownIcon = packIcon("chevron-down");
/** A chevron that points right, from the chosen icon pack. */
export const ChevronRightIcon = packIcon("chevron-right");
/** A check mark in a circle, from the chosen icon pack. */
export const CircleCheckIcon = packIcon("circle-check");
/** A cross in a circle, from the chosen icon pack. */
export const CircleXIcon = packIcon("circle-x");
/** A download arrow, from the chosen icon pack. */
export const DownloadIcon = packIcon("download");
/** A globe, from the chosen icon pack. */
export const GlobeIcon = packIcon("globe");
/** An expand mark, from the chosen icon pack. */
export const MaximizeIcon = packIcon("expand");
/** A speech bubble, from the chosen icon pack. */
export const MessageIcon = packIcon("message");
/** A play mark, from the chosen icon pack. */
export const PlayerPlayFilledIcon = packIcon("play");
/** A plus, from the chosen icon pack. */
export const PlusIcon = packIcon("plus");
