/** Props for a change figure. */
export interface DeltaProps {
  /** The percent change. */
  value: number;
  /** Set when a fall is the good direction, such as no-shows or waiting time. */
  lowerIsBetter?: boolean;
  className?: string;
}

/**
 * A percent change with an arrow. The arrow and the spoken word carry the
 * direction, and the colour says only whether the change is good.
 */
export function Delta({ value, lowerIsBetter = false, className }: DeltaProps) {
  const flat = Math.abs(value) < 0.05;
  const up = value > 0;
  const good = flat ? null : up !== lowerIsBetter;
  const Arrow = up ? ArrowUpIcon : ArrowDownIcon;
  return (
    <span
      className={cn(
        "inline-flex items-center gap-0.5 text-xs font-medium tabular-nums",
        good === null ? "text-muted-foreground" : STATUS_TEXT[good ? "good" : "bad"],
        className,
      )}
    >
      {flat ? null : <Arrow aria-hidden="true" className="size-3" />}
      <span className="sr-only">{flat ? "No change" : up ? "Up" : "Down"}</span>
      {formatPercent(value)}
    </span>
  );
}

