/** Props for the detail view of one figure. */
export interface KpiDetailProps {
  kpi: Kpi;
  range: KpiRange;
  /** Draws the period before on the chart and adds it to the table. */
  compare: boolean;
  onClose: () => void;
  /** The Close button, so the block can move focus to it when the view opens. */
  closeRef?: RefObject<HTMLButtonElement | null>;
}

/**
 * One figure opened up: its daily trend against the period before, then the
 * clinics behind it. Escape clears the inspected day first, then closes.
 * It fills the height it is given, so it can cover the grid of cards.
 */
export function KpiDetail({ kpi, range, compare, onClose, closeRef }: KpiDetailProps) {
  const figures = readKpi(kpi, range);
  const length = figures.current.length;
  const cursor = usePointCursor(length);
  const dayOf = (index: number) => sampleDate(length - 1 - index);

  const peak = figures.current.indexOf(Math.max(...figures.current));
  // One short result that the headline figure does not already state.
  const summary = `${kpi.label} peaked on ${formatWeekday(dayOf(peak))}, ${formatDay(dayOf(peak))}.`;

  const describePoint = (index: number) => {
    const base = `${formatDay(dayOf(index))}: ${formatWhole(figures.current[index] ?? 0)}`;
    return compare
      ? `${base}, against ${formatWhole(figures.previous[index] ?? 0)} on the same day of the period before.`
      : `${base}.`;
  };

  const pointDetails = (index: number) => {
    const value = figures.current[index] ?? 0;
    const earlier = figures.previous[index] ?? 0;
    const change = percentChange(earlier, value);
    return {
      title: `${formatWeekday(dayOf(index))}, ${formatDay(dayOf(index))}`,
      rows: compare
        ? [
            { label: kpi.label, value: formatWhole(value), marker: "bg-chart-1" },
            { label: `${range} days before`, value: formatWhole(earlier), marker: "bg-muted-foreground", dashed: true },
          ]
        : [{ label: kpi.label, value: formatWhole(value), marker: "bg-chart-1" }],
      note: compare ? `${change >= 0 ? "Up" : "Down"} ${formatOnePlace(Math.abs(change))}% on that day` : undefined,
    };
  };

  // The chart handles Escape first when a day is inspected, and marks the event as handled.
  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key !== "Escape" || event.defaultPrevented) return;
    event.preventDefault();
    onClose();
  };

  return (
    <div role="group" aria-label={`${kpi.label} detail`} onKeyDown={handleKeyDown} className="flex h-full flex-col gap-6 p-5">
      <div className="flex items-start justify-between gap-4">
        <div className="flex min-w-0 flex-col gap-1">
          <h3 className="text-sm text-muted-foreground">{kpi.label}</h3>
          <p className="text-3xl font-semibold tracking-tight tabular-nums">
            <NumberTicker value={Math.round(figures.now)} format={ROLL_WHOLE} />
          </p>
          {/* The line keeps its height when the comparison is off, so the view never changes size. */}
          <p className={cn("flex h-4 items-center gap-1.5 text-xs whitespace-nowrap text-muted-foreground", compare ? undefined : "invisible")}>
            <Delta value={figures.change} lowerIsBetter={kpi.lowerIsBetter} />
            vs {formatWhole(figures.before)} before
          </p>
        </div>
        <Button ref={closeRef} variant="outline" size="sm" onClick={onClose} className="min-h-11 sm:min-h-8">
          <XIcon aria-hidden="true" className="size-4" />
          Close
        </Button>
      </div>

      <TrendChart
        label={`${kpi.label}, last ${range} days`}
        values={figures.current}
        compare={compare ? figures.previous : null}
        axisLabels={[formatDay(dayOf(0)), formatDay(dayOf(Math.floor((length - 1) / 2))), formatDay(dayOf(length - 1))]}
        formatAxis={formatWhole}
        describePoint={describePoint}
        pointDetails={pointDetails}
        summary={summary}
        cursor={cursor}
      />

      <div className="flex flex-col gap-2 border-t border-border pt-5">
        <h3 className="text-sm font-medium">{kpi.label} by clinic</h3>
        <BreakdownTable
          label={`${kpi.label} by clinic, last ${range} days`}
          rows={clinicRows(kpi, range)}
          total={figures.now}
          totalBefore={figures.before}
          totalChange={figures.change}
          lowerIsBetter={kpi.lowerIsBetter}
          compare={compare}
        />
      </div>
    </div>
  );
}

"use client";

import { type KeyboardEvent, type PointerEvent, useCallback, useState } from "react";

/** What a chart needs to let a person inspect one point with a pointer or the keyboard. */
export interface PointCursor {
  /** The inspected point, or null when nothing is inspected. */
  index: number | null;
  setIndex: (index: number | null) => void;
  /** Spread onto the focusable plot. Arrows step, Page keys jump, Home and End go to the ends, Escape clears. */
  plotProps: {
    tabIndex: 0;
    onKeyDown: (event: KeyboardEvent<HTMLElement>) => void;
    /** A tap or a press inspects the point under it, so a touch screen needs no hover. */
    onPointerDown: (event: PointerEvent<HTMLElement>) => void;
    onPointerMove: (event: PointerEvent<HTMLElement>) => void;
    onPointerLeave: (event: PointerEvent<HTMLElement>) => void;
    /** A finger can scrub across the plot while the page still scrolls up and down. */
    style: { touchAction: "pan-y" };
    onBlur: () => void;
  };
}

/**
 * Tracks the inspected point of a plot with `length` points. `pageStep` is how
 * far the Page keys and Shift with an arrow jump.
 */
export function usePointCursor(length: number, pageStep = 7): PointCursor {
  const [raw, setIndex] = useState<number | null>(null);
  // A shorter range can leave the cursor past the end, so clamp on read.
  const index = raw === null ? null : Math.min(raw, length - 1);

  const onKeyDown = useCallback(
    (event: KeyboardEvent<HTMLElement>) => {
      const last = length - 1;
      const current = index ?? last;
      const big = event.shiftKey ? pageStep : 1;
      let next: number | null;
      if (event.key === "ArrowLeft") next = index === null ? last : Math.max(0, current - big);
      else if (event.key === "ArrowRight") next = index === null ? last : Math.min(last, current + big);
      else if (event.key === "PageUp") next = Math.max(0, current - pageStep);
      else if (event.key === "PageDown") next = Math.min(last, current + pageStep);
      else if (event.key === "Home") next = 0;
      else if (event.key === "End") next = last;
      else if (event.key === "Escape" && index !== null) next = null;
      else return;
      event.preventDefault();
      setIndex(next);
    },
    [index, length, pageStep],
  );

  const onPointerMove = useCallback(
    (event: PointerEvent<HTMLElement>) => {
      const box = event.currentTarget.getBoundingClientRect();
      if (box.width === 0) return;
      const ratio = Math.min(1, Math.max(0, (event.clientX - box.left) / box.width));
      setIndex(Math.round(ratio * (length - 1)));
    },
    [length],
  );

  const clear = useCallback(() => setIndex(null), []);

  // A finger leaves the plot the moment it lifts. Clearing then would hide the point a tap just chose,
  // so only a mouse clears on the way out. A tapped point stays until the plot loses focus.
  const onPointerLeave = useCallback((event: PointerEvent<HTMLElement>) => {
    if (event.pointerType === "mouse") setIndex(null);
  }, []);

  return {
    index,
    setIndex,
    plotProps: {
      tabIndex: 0,
      onKeyDown,
      onPointerDown: onPointerMove,
      onPointerMove,
      onPointerLeave,
      onBlur: clear,
      style: { touchAction: "pan-y" },
    },
  };
}

"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";

import { cn } from "@/lib/utils";

import { areaPath, axisTicks, linePath, paddedExtent, toX, toY } from "../lib/plot";
import type { PointCursor } from "../lib/use-point-cursor";
import { PointTip, type PointTipProps } from "./point-tip";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for a trend chart. */
export interface TrendChartProps {
  /** Names the chart for screen readers, such as "Bookings, last 30 days". */
  label: string;
  values: number[];
  /** The earlier period, drawn as a dashed line. Null hides it. */
  compare: number[] | null;
  /** A short label for the first, middle and last point of the axis. */
  axisLabels: [string, string, string];
  formatAxis: (value: number) => string;
  /** The sentence shown for the inspected point, also read to screen readers. */
  describePoint: (index: number) => string;
  /** The details shown in the card beside the inspected point. Without it, the sentence above the plot changes instead. */
  pointDetails?: (index: number) => Pick<PointTipProps, "title" | "rows" | "note">;
  /** The sentence shown when no point is inspected. */
  summary: string;
  cursor: PointCursor;
  className?: string;
}

// Critically damped: the line settles on its new shape with no wobble.
const MORPH: Transition = { type: "spring", stiffness: 260, damping: 32, mass: 1 };
const INSTANT: Transition = { duration: 0 };

/**
 * One line over time with an optional earlier period behind it. The plot is a
 * single tab stop: arrows inspect a point, Home and End jump, Escape clears.
 * The readout sits above the plot, so it never covers the line it describes.
 */
export function TrendChart({
  label,
  values,
  compare,
  axisLabels,
  formatAxis,
  describePoint,
  pointDetails,
  summary,
  cursor,
  className,
}: TrendChartProps) {
  const reduceMotion = useReducedMotion();
  const transition = reduceMotion ? INSTANT : MORPH;
  const extent = paddedExtent(compare ? [values, compare] : [values]);
  const ticks = axisTicks(extent).reverse();
  const { index } = cursor;
  const pointValue = index === null ? null : values[index];

  return (
    <div className={cn("flex min-h-0 flex-1 flex-col gap-3", className)}>
      <p className="h-5 truncate text-sm text-muted-foreground">{index === null || pointDetails ? summary : describePoint(index)}</p>
      <p aria-live="polite" className="sr-only">
        {index === null ? "" : describePoint(index)}
      </p>
      <div className="flex min-h-0 flex-1 gap-3">
        <div aria-hidden="true" className="mb-6 flex w-9 shrink-0 flex-col justify-between text-right text-xs tabular-nums text-muted-foreground">
          {ticks.map((tick) => (
            <span key={tick} className="-my-2 leading-4">
              {formatAxis(tick)}
            </span>
          ))}
        </div>
        <div className="flex min-w-0 flex-1 flex-col">
          <div
            {...cursor.plotProps}
            role="application"
            aria-roledescription="chart"
            aria-label={`${label}. Use the arrow keys to read each point.`}
            className="relative min-h-56 flex-1 cursor-crosshair touch-pan-y rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-4 focus-visible:ring-offset-card"
          >
            <div aria-hidden="true" className="absolute inset-0 flex flex-col justify-between">
              {ticks.map((tick) => (
                <span key={tick} className="h-px w-full bg-border/60" />
              ))}
            </div>
            <svg aria-hidden="true" viewBox="0 0 100 100" preserveAspectRatio="none" className="absolute inset-0 size-full overflow-visible">
              <motion.path
                initial={false}
                animate={{ d: areaPath(values, extent) }}
                transition={transition}
                className="fill-chart-1/10"
              />
              {compare ? (
                <motion.path
                  initial={{ opacity: 0, d: linePath(compare, extent) }}
                  animate={{ opacity: 1, d: linePath(compare, extent) }}
                  transition={transition}
                  fill="none"
                  strokeWidth="1.5"
                  strokeDasharray="4 4"
                  vectorEffect="non-scaling-stroke"
                  className="stroke-muted-foreground/70"
                />
              ) : null}
              <motion.path
                initial={false}
                animate={{ d: linePath(values, extent) }}
                transition={transition}
                fill="none"
                strokeWidth="2"
                strokeLinejoin="round"
                vectorEffect="non-scaling-stroke"
                className="stroke-chart-1"
              />
            </svg>
            {index !== null && pointValue !== undefined && pointValue !== null ? (
              <div aria-hidden="true" className="left-(--x) pointer-events-none absolute inset-y-0" style={
                // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                { "--x": `${toX(index, values.length)}%` } as VarStyle
              }>
                <span className="absolute inset-y-0 -left-px w-px bg-foreground/30" />
                <span
                  className="top-(--y) absolute -left-2 size-4 -translate-y-1/2 rounded-full border-2 border-chart-1 bg-card shadow-sm"
                  style={
                    // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                    { "--y": `${toY(pointValue, extent)}%` } as VarStyle
                  }
                />
              </div>
            ) : null}
            {index !== null && pointValue !== undefined && pointValue !== null && pointDetails ? (
              <PointTip x={toX(index, values.length)} y={toY(pointValue, extent)} {...pointDetails(index)} />
            ) : null}
          </div>
          <div aria-hidden="true" className="mt-2 flex justify-between text-xs text-muted-foreground">
            {axisLabels.map((text, position) => (
              <span key={`${text}-${position}`}>{text}</span>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

import { cn } from "@/lib/utils";

import type { VarStyle } from "@/components/blocks/lib/css-vars";
import { RollingText } from "./rolling-text";

/** One line of a point's details. */
export interface PointTipRow {
  label: string;
  value: string;
  /** A class that colours the row's marker, such as `bg-chart-1`. Omit for a row with no series. */
  marker?: string;
  /** Draws the marker as a dashed line, for an earlier period. */
  dashed?: boolean;
}

/** Props for the card that shows one point's details. */
export interface PointTipProps {
  /** Where the point sits in its plot, from 0 to 100 on each axis, measured from the top left. */
  x: number;
  y: number;
  title: string;
  rows: PointTipRow[];
  /** A closing line, such as the difference between two rows. */
  note?: string;
  className?: string;
}

/**
 * A small card beside an inspected point. It sits on the side of the point
 * with more room and stays inside the plot. In a plot narrower than the card
 * and the point together, it may cover the point rather than be cut off.
 * The digits of each value roll to the next point's figure as the point changes.
 * The card blurs what is behind it, so a design system with a see-through popover stays legible.
 * It is decorative for screen readers: the plot's live readout says the same.
 */
export function PointTip({ x, y, title, rows, note, className }: PointTipProps) {
  const onLeft = x > 55;
  return (
    <div
      aria-hidden="true"
      className={cn("pointer-events-none absolute top-(--y) z-10", onLeft ? "right-(--side)" : "left-(--side)", className)}
      style={
        // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
        {
          // The card hangs one rem from the point, but never past the plot's edge: 14rem is its widest.
          "--side": `min(calc(${onLeft ? 100 - x : x}% + 1rem), calc(100% - 14rem))`,
          "--y": `${Math.min(78, Math.max(22, y))}%`,
        } as VarStyle
      }
    >
      <div
        className={cn(
          "flex w-max max-w-56 -translate-y-1/2 flex-col gap-1.5 rounded-xl border border-border bg-popover px-3 py-2 text-popover-foreground shadow-lg backdrop-blur-md",
        )}
      >
        <span className="text-xs text-muted-foreground">{title}</span>
        {rows.map((row) => (
          <span key={row.label} className="flex items-center justify-between gap-6 text-sm">
            <span className="flex items-center gap-2 text-muted-foreground">
              {row.marker ? (
                <span className={cn("h-0.5 w-3 rounded-full", row.dashed ? "border-t border-dashed border-current" : row.marker)} />
              ) : null}
              {row.label}
            </span>
            <RollingText text={row.value} className="font-medium" />
          </span>
        ))}
        {note ? <span className="border-t border-border pt-1.5 text-xs text-muted-foreground">{note}</span> : null}
      </div>
    </div>
  );
}

import type { CSSProperties } from "react";

/**
 * An inline style made only of custom properties, for values known at render
 * such as a point's place in a plot. Classes read them, as `left-(--x)` does.
 */
export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

