          <tr className="border-b border-border">
            <th scope="col" className="h-10 align-middle whitespace-nowrap font-medium text-left text-muted-foreground pr-2">Clinic</th>
            <th scope="col" className="h-10 px-2 align-middle whitespace-nowrap font-medium text-right text-muted-foreground">This period</th>
            {compare ? (
              <>
                <th scope="col" className="h-10 px-2 align-middle whitespace-nowrap font-medium hidden text-right text-muted-foreground @md:table-cell">Period before</th>
                <th scope="col" className="h-10 px-2 align-middle whitespace-nowrap font-medium text-right text-muted-foreground">Change</th>
              </>
            ) : null}
            <th scope="col" className="h-10 align-middle whitespace-nowrap font-medium text-left w-2/5 text-muted-foreground pl-2">Share of total</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr key={row.clinic} className="border-b border-border">
              <th scope="row" className="h-10 align-middle whitespace-nowrap text-left font-normal pr-2">{row.clinic}</th>
              <td className="h-10 px-2 align-middle whitespace-nowrap text-right tabular-nums">{formatWhole(row.now)}</td>
              {compare ? (
                <>
                  <td className="h-10 px-2 align-middle whitespace-nowrap hidden text-right text-muted-foreground tabular-nums @md:table-cell">
                    {formatWhole(row.before)}
                  </td>
                  <td className="h-10 px-2 align-middle whitespace-nowrap text-right">
                    <Delta value={row.change} lowerIsBetter={lowerIsBetter} />
                  </td>
                </>
              ) : null}
              <td className="h-10 align-middle whitespace-nowrap pl-2">
                <span className="flex items-center gap-3">
                  <span aria-hidden="true" className="hidden h-1.5 flex-1 overflow-hidden rounded-full bg-muted @md:block">
                    <span className="w-(--w) block h-full rounded-full bg-chart-1" style={
                      // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                      { "--w": `${row.share}%` } as VarStyle
                    } />
                  </span>
                  <span className="w-12 text-right text-muted-foreground tabular-nums">{formatOnePlace(row.share)}%</span>
                </span>
              </td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr className="border-b border-border last:border-b-0">
            <th scope="row" className="h-10 align-middle whitespace-nowrap font-medium text-left pr-2">All clinics</th>
            <td className="h-10 px-2 align-middle whitespace-nowrap text-right tabular-nums">{formatWhole(total)}</td>
            {compare ? (
              <>
                <td className="h-10 px-2 align-middle whitespace-nowrap hidden text-right text-muted-foreground tabular-nums @md:table-cell">
                  {formatWhole(totalBefore)}
                </td>
                <td className="h-10 px-2 align-middle whitespace-nowrap text-right">
                  <Delta value={totalChange} lowerIsBetter={lowerIsBetter} />
                </td>
              </>
            ) : null}
            <td className="h-10 align-middle whitespace-nowrap pl-2">
              <span className="flex justify-end text-muted-foreground tabular-nums">100.0%</span>
            </td>
          </tr>
        </tfoot>
      </Table>
  );
}
